import Axios from '@/server'
import type { Result } from '@/server/types'
import { GoodsTypes } from './types'

/**
 * 获取商品详情
 * @param goodsId 商品ID
 */
export const getGoodsDetail = (goodsId: number) =>
  Axios.request<Result<GoodsTypes.DetailGoodsRes>>({
    url: `/admin/goods/${goodsId}/detail`,
    method: 'GET'
  })

/**
 * 更新商品状态(上下架/删除)
 * @param goodsId 商品ID
 * @param data 更新状态请求参数
 */
export const updateGoodsStatus = (goodsId: number, data: GoodsTypes.UpdateStatusGoodsReq) =>
  Axios.request<Result>({
    url: `/admin/goods/${goodsId}/update-status`,
    method: 'POST',
    data
  })

/**
 * 添加新的商品
 * @param data 添加商品请求参数
 */
export const addGoods = (data: GoodsTypes.AddGoodsReq) =>
  Axios.request<Result>({
    url: '/admin/goods/add-new-goods',
    method: 'POST',
    data
  })

/**
 * 编辑商品
 * @param goodsId 商品ID
 * @param data 编辑商品请求参数
 */
export const editGoods = (goodsId: number, data: GoodsTypes.EditGoodsReq) =>
  Axios.request<Result>({
    url: `/admin/goods/${goodsId}/edit`,
    method: 'POST',
    data
  })

/**
 * 批量更新商品状态(上下架/删除)
 * @param data 批量更新请求参数
 */
export const batchUpdateGoodsStatus = (data: GoodsTypes.BatchUpdateStatusGoodsReq) =>
  Axios.request<Result>({
    url: '/admin/goods/batch-update-status',
    method: 'POST',
    data
  })

/**
 * 获取商品列表
 * @param params 查询参数
 */
export const getGoodsList = (params?: GoodsTypes.GoodsListReq) =>
  Axios.request<Result<GoodsTypes.GoodsListRes>>({
    url: '/admin/goods/list',
    method: 'GET',
    params
  })

/**
 * 商品管理类型命名空间
 * @example
 * ```typescript
 * import { goodsApi } from '@/apis';
 * const params: goodsApi.GoodsTypes.GoodsListReq = { page: 1 };
 * ```
 */
export type { GoodsTypes }
